      if(!best){ const blk=[...t.querySelectorAll('.nx-tbl,.nx-hlg,.nx-kl2,.nx-ggr,.nx-fgr,.mms-pl,.nx-ml2,.nx-tl2,.nx-ag')].filter(k=>!k.hidden && k.getClientRects().length && !k.closest(NOCUT)).pop(); if(blk){ blk.hidden=true; continue; } }
