      if(!best){ const vis=k=>k && !k.hidden && k.getClientRects().length; const ms=t.querySelector('.mic-steps'), nx=[...t.querySelectorAll('.st-next')].filter(vis).pop(); const opt=vis(ms) ? ms : nx; if(opt){ opt.hidden=true; continue; } }
